+document.addEventListener('DOMContentLoaded', () => {
+    // Cart functionality
+    const cartCountElement = document.getElementById('cart-count');
+    const addToCartButtons = document.querySelectorAll('.add-to-cart');
+    let cartCount = 0;
+
+    addToCartButtons.forEach(button => {
+        button.addEventListener('click', () => {
+            cartCount++;
+            cartCountElement.textContent = cartCount;
+            
+            // Visual feedback
+            const originalText = button.textContent;
+            button.textContent = 'Added!';
+            button.style.backgroundColor = '#4CAF50';
+            button.style.color = 'white';
+            button.style.borderColor = '#4CAF50';
+
+            setTimeout(() => {
+                button.textContent = originalText;
+                button.style.backgroundColor = 'transparent';
+                button.style.color = 'inherit';
+                button.style.borderColor = '#1a1a1a';
+            }, 1500);
+        });
+    });
+
+    // Countdown Timer logic (simulated)
+    const updateCountdown = () => {
+        const hoursElement = document.getElementById('hours');
+        const minutesElement = document.getElementById('minutes');
+        
+        let hours = parseInt(hoursElement.textContent);
+        let minutes = parseInt(minutesElement.textContent);
+
+        if (minutes > 0) {
+            minutes--;
+        } else {
+            if (hours > 0) {
+                hours--;
+                minutes = 59;
+            }
+        }
+
+        hoursElement.textContent = hours.toString().padStart(2, '0');
+        minutesElement.textContent = minutes.toString().padStart(2, '0');
+    };
+
+    setInterval(updateCountdown, 60000); // Update every minute
+
+    // Newsletter form
+    const newsletterForm = document.getElementById('newsletter-form');
+    if (newsletterForm) {
+        newsletterForm.addEventListener('submit', (e) => {
+            e.preventDefault();
+            const email = newsletterForm.querySelector('input').value;
+            alert(`Thank you for subscribing with: ${email}`);
+            newsletterForm.reset();
+        });
+    }
+
+    // Smooth scroll for nav links
+    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
+        anchor.addEventListener('click', function (e) {
+            e.preventDefault();
+            const target = document.querySelector(this.getAttribute('href'));
+            if (target) {
+                target.scrollIntoView({
+                    behavior: 'smooth'
+                });
+            }
+        });
+    });
+});
+
', direction=None, fact=None, file_name='/workspace/sandbox/control/shopping-home-page--framework-vanilla-js--style-modern/google/gemini-3-flash-preview__s1/script.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Create file', new_file_contents='document.addEventListener('DOMContentLoaded', () => {
    // Cart functionality
    const cartCountElement = document.getElementById('cart-count');
    const addToCartButtons = document.querySelectorAll('.add-to-cart');
    let cartCount = 0;

    addToCartButtons.forEach(button => {
        button.addEventListener('click', () => {
            cartCount++;
            cartCountElement.textContent = cartCount;

            // Visual feedback
            const originalText = button.textContent;
            button.textContent = 'Added!';
            button.style.backgroundColor = '#4CAF50';
            button.style.color = 'white';
            button.style.borderColor = '#4CAF50';

            setTimeout(() => {
                button.textContent = originalText;
                button.style.backgroundColor = 'transparent';
                button.style.color = 'inherit';
                button.style.borderColor = '#1a1a1a';
            }, 1500);
        });
    });

    // Countdown Timer logic (simulated)
    const updateCountdown = () => {
        const hoursElement = document.getElementById('hours');
        const minutesElement = document.getElementById('minutes');

        let hours = parseInt(hoursElement.textContent);
        let minutes = parseInt(minutesElement.textContent);

        if (minutes > 0) {
            minutes--;
        } else {
            if (hours > 0) {
                hours--;
                minutes = 59;
            }
        }

        hoursElement.textContent = hours.toString().padStart(2, '0');
        minutesElement.textContent = minutes.toString().padStart(2, '0');
    };

    setInterval(updateCountdown, 60000); // Update every minute

    // Newsletter form
    const newsletterForm = document.getElementById('newsletter-form');
    if (newsletterForm) {
        newsletterForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const email = newsletterForm.querySelector('input').value;
            alert(`Thank you for subscribing with: ${email}`);
            newsletterForm.reset();
        });
    }

    // Smooth scroll for nav links
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
            e.preventDefault();
            const target = document.querySelector(this.getAttribute('href'));
            if (target) {
                target.scrollIntoView({
                    behavior: 'smooth'
                });
            }
        });
    });
});
