    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: -1px;
    color: var(--primary-color);
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    font-weight: 500;
    font-size: 0.9rem;
    color: var(--text-color);
    transition: var(--transition);
}

.nav-links a:hover {
    color: var(--accent-color);
}

.cart-icon {
    position: relative;
    cursor: pointer;
}

#cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background: var(--accent-color);
    color: white;
    font-size: 0.7rem;
    padding: 2px 6px;
    border-radius: 50%;
    font-weight: bold;
}

/* Hero Section */
.hero {
    padding: 6rem 0;
    background-color: var(--secondary-color);
    margin-bottom: 4rem;
}

.hero-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: center;
    gap: 4rem;
}

.hero-text h1 {
    font-size: 3.5rem;
    line-height: 1.1;
    margin: 1.5rem 0;
    font-weight: 800;
}

.badge {
    background: var(--accent-color);
    color: white;
    padding: 0.4rem 1rem;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
}

.hero-text p {
    font-size: 1.1rem;
    color: var(--light-text);
    margin-bottom: 2rem;
    max-width: 500px;
}

.btn {
    display: inline-block;
    background: var(--primary-color);
    color: white;
    padding: 1rem 2.5rem;
    border-radius: 4px;
    font-weight: 600;
    transition: var(--transition);
}

.btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 10px 20px rgba(0,0,0,0.1);
}

.btn-dark {
    background: var(--primary-color);
}

.hero-image img {
    border-radius: 8px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.1);
}

/* Product Section */
.section-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 2.5rem;
}

.section-header h2 {
    font-size: 2rem;
    font-weight: 700;
}

.view-all {
    font-weight: 600;
    color: var(--accent-color);
    border-bottom: 2px solid transparent;
    transition: var(--transition);
}

.view-all:hover {
    border-bottom-color: var(--accent-color);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
    margin-bottom: 5rem;
}

.product-card {
    background: white;
    transition: var(--transition);
}

.product-img {
    background: #f9f9f9;
    padding: 2rem;
    border-radius: 8px;
    margin-bottom: 1rem;
    overflow: hidden;
    aspect-ratio: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.product-img img {
    transition: var(--transition);
}

.product-card:hover .product-img img {
    transform: scale(1.05);
}

.product-info h3 {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.price {
    font-weight: 700;
    color: var(--primary-color);
    margin-bottom: 1rem;
}

.add-to-cart {
    width: 100%;
    padding: 0.8rem;
    background: transparent;
    border: 1px solid var(--primary-color);
    border-radius: 4px;
    font-weight: 600;
    cursor: pointer;
    transition: var(--transition);
}

.add-to-cart:hover {
    background: var(--primary-color);
    color: white;
}

/* Deals Section */
.deals-section {
    background: #1a1a1a;
    color: white;
    padding: 5rem 0;
    margin: 5rem 0;
    background-image: linear-gradient(rgba(0,0,0,0.7), rgba(0,0,0,0.7)), url('https://images.unsplash.com/photo-1511556820780-d912e42b4980?auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
}

.deal-content {
    max-width: 500px;
}

.deal-content h2 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.deal-content p {
    color: #ccc;
    margin-bottom: 2rem;
}

.countdown {
    display: flex;
    gap: 2rem;
    margin-bottom: 2.5rem;
}

.time-unit {
    display: flex;
    flex-direction: column;
}

.time-unit span {
    font-size: 2rem;
    font-weight: 700;
}

.time-unit label {
    font-size: 0.8rem;
    text-transform: uppercase;
    color: #888;
}

.btn-dark {
    background: white;
    color: black;
}

/* Journal Section */
.journal-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 3rem;
    margin-bottom: 5rem;
}

.journal-item img {
    border-radius: 8px;
    margin-bottom: 1.5rem;
}

.journal-info .date {
    font-size: 0.8rem;
    color: var(--light-text);
    text-transform: uppercase;
    font-weight: 600;
}

.journal-info h3 {
    font-size: 1.5rem;
    margin: 0.5rem 0 1rem;
}

.journal-info p {
    color: var(--light-text);
    margin-bottom: 1.5rem;
}

.read-more {
    font-weight: 600;
    border-bottom: 2px solid var(--primary-color);
}

/* Footer */
footer {
    background: #f9f9f9;
    padding: 5rem 0 2rem;
    border-top: 1px solid #eee;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: 4rem;
    margin-bottom: 4rem;
}

.footer-info p {
    margin-top: 1.5rem;
    color: var(--light-text);
}

.footer-links h4, .footer-newsletter h4 {
    margin-bottom: 1.5rem;
    font-size: 1.1rem;
}

.footer-links li {
    margin-bottom: 0.8rem;
}

.footer-links a {
    color: var(--light-text);
    transition: var(--transition);
}

.footer-links a:hover {
    color: var(--accent-color);
}

.footer-newsletter p {
    color: var(--light-text);
    margin-bottom: 1.5rem;
}

#newsletter-form {
    display: flex;
    gap: 0.5rem;
}

#newsletter-form input {
    flex: 1;
    padding: 0.8rem;
    border: 1px solid #ddd;
    border-radius: 4px;
}

#newsletter-form button {
    padding: 0.8rem 1.5rem;
    background: var(--primary-color);
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.footer-bottom {
    padding-top: 2rem;
    border-top: 1px solid #eee;
    text-align: center;
    color: var(--light-text);
    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 992px) {
    .hero-content {
        grid-template-columns: 1fr;
        text-align: center;
    }
    .hero-text p {
        margin-left: auto;
        margin-right: auto;
    }
    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
}

@media (max-width: 768px) {
    .nav-links {
        display: none;
    }
    .journal-grid {
        grid-template-columns: 1fr;
    }
}
